class Solution {
public:
    long long maxOutput(int n, vector<vector<int>>& edges, vector<int>& price) {
        if (n == 1) return 0;
        vector<int> head(n, -1), nxt(2 * (n - 1)), dst(2 * (n - 1));
        for (int i = 0; i < n - 1; ++i) {
            int a = edges[i][0], b = edges[i][1];
            dst[2*i] = b;     nxt[2*i] = head[a]; head[a] = 2*i;
            dst[2*i+1] = a;   nxt[2*i+1] = head[b]; head[b] = 2*i+1;
        }
        vector<int> par(n, -1), order;
        order.reserve(n);
        order.push_back(0);
        par[0] = 0;
        for (int i = 0; i < (int)order.size(); ++i) {
            int u = order[i];
            for (int e = head[u]; e != -1; e = nxt[e]) {
                int v = dst[e];
                if (v != par[u]) { par[v] = u; order.push_back(v); }
            }
        }
        // g[v] = max downward path sum from v into its subtree (children only)
        vector<long long> g(n), up(n), best1(n, 0), best2(n, 0);
        for (int i = n - 1; i >= 0; --i) {
            int v = order[i];
            g[v] = price[v] + best1[v];
            int p = par[v];
            if (v != p) {
                if (g[v] > best1[p]) { best2[p] = best1[p]; best1[p] = g[v]; }
                else if (g[v] > best2[p]) best2[p] = g[v];
            }
        }
        long long ans = 0;
        for (int i = 0; i < n; ++i) {
            int v = order[i];
            if (v == 0) { up[v] = price[v]; continue; }
            int p = par[v];
            long long sib = (g[v] < best1[p]) ? best1[p] : best2[p];
            // path v -> p -> best sibling subtree (needs price[p]) OR continue upward (up[p] already has price[p])
            up[v] = price[v] + max(sib + (long long)price[p], up[p]);
            long long cand = max(best1[v], up[v] - price[v]);
            if (cand > ans) ans = cand;
        }
        return ans;
    }
};
